{
  "id": "convertToCelsius",
  "type": "core.action.script",
  "typeVersion": "1.0",
  "display": {
    "label": "Convert to Celsius"
  },
  "inputs": {
    "script": "const tempF = $vars.getWeather.output.body.current.temperature_2m;\nconst tempC = (tempF - 32) * 5 / 9;\nreturn {\n  temperatureF: tempF,\n  temperatureC: tempC\n};"
  },
  "outputs": {
    "output": {
      "type": "object",
      "description": "The return value of the script",
      "source": {
        "type": "literal",
        "expression": "=result.response",
        "fieldType": "string"
      },
      "var": "output"
    },
    "error": {
      "type": "object",
      "description": "Error information if the script fails",
      "source": {
        "type": "literal",
        "expression": "=result.Error",
        "fieldType": "string"
      },
      "var": "error"
    }
  },
  "model": {
    "type": "bpmn:ScriptTask"
  }
},
{
  "id": "formatSummary",
  "type": "core.action.script",
  "typeVersion": "1.0",
  "display": {
    "label": "Format Weather Summary"
  },
  "inputs": {
    "script": "const tempF = $vars.convertToCelsius.output.temperatureF;\nconst tempC = $vars.convertToCelsius.output.temperatureC;\nconst time = $vars.getWeather.output.body.current.time;\nreturn {\n  temperatureF: tempF,\n  temperatureC: tempC,\n  summary: 'Bellevue weather today: ' + tempF + 'F (' + tempC.toFixed(1) + 'C) at ' + time\n};"
  },

